-- Read-only metadata preflight; no source rows, user records or credentials.
-- 27 Oct 2026: execute_sql produced no result within the 45-second tool bound.
-- Retained for the governed migration review; do not infer readiness from timeout.
select jsonb_build_object(
 'measured_at',clock_timestamp(),'server_version',current_setting('server_version'),
 'roles',(select jsonb_agg(jsonb_build_object('name',rolname,'superuser',rolsuper,'bypass_rls',rolbypassrls,'can_login',rolcanlogin) order by rolname) from pg_roles where rolname in ('tcg_api','postgres','anon','authenticated')),
 'relations',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'runtime_select',has_table_privilege('tcg_api',c.oid,'SELECT'),'runtime_insert',has_table_privilege('tcg_api',c.oid,'INSERT'),'runtime_update',has_table_privilege('tcg_api',c.oid,'UPDATE'),'runtime_delete',has_table_privilege('tcg_api',c.oid,'DELETE')) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='tcg' and c.relname in ('owners','owner_memberships','founder_app_accounts','import_batches','import_candidates','inventory_items','audit_events') and c.relkind in ('r','p')),
 'batch_columns',(select jsonb_agg(jsonb_build_object('column',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'runtime_update',has_column_privilege('tcg_api',a.attrelid,a.attnum,'UPDATE')) order by a.attnum) from pg_attribute a where a.attrelid=to_regclass('tcg.import_batches') and a.attnum>0 and not a.attisdropped),
 'private_schema',(select jsonb_build_object('owner',pg_get_userbyid(nspowner),'runtime_usage',has_schema_privilege('tcg_api',oid,'USAGE'),'runtime_create',has_schema_privilege('tcg_api',oid,'CREATE'),'anon_usage',has_schema_privilege('anon',oid,'USAGE'),'authenticated_usage',has_schema_privilege('authenticated',oid,'USAGE'),'acl',nspacl::text) from pg_namespace where nspname='tcg_private'),
 'functions',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'identity_args',pg_get_function_identity_arguments(p.oid),'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'config',p.proconfig,'runtime_execute',has_function_privilege('tcg_api',p.oid,'EXECUTE'),'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'),'definition',case when p.proname in ('current_user_id','is_platform_admin') then pg_get_functiondef(p.oid) else null end) order by n.nspname,p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname='tcg' and p.proname in ('current_user_id','is_platform_admin','audit_import_candidate_change')) or (n.nspname='tcg_private' and p.proname='replace_import_preview')),
 'import_policies',(select jsonb_agg(jsonb_build_object('table',tablename,'name',policyname,'roles',roles,'command',cmd,'using',qual,'check',with_check) order by tablename,policyname) from pg_policies where schemaname='tcg' and tablename in ('import_batches','import_candidates')),
 'candidate_triggers',(select jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid)) order by t.tgname) from pg_trigger t where t.tgrelid=to_regclass('tcg.import_candidates') and not t.tgisinternal),
 'migration_present',(select exists(select 1 from supabase_migrations.schema_migrations where version='20261027143430'))
) as import_rebuild_preflight;
